_TLEVEL = "SYNTHETIC HYDRUS T_LEVEL fixture; no field observations\nTime rTop vTop vBot hTop hBot\n[d] [m/d] [m/d] [m/d] [m] [m]\n0 0.001 0.0008 -0.0001 -0.1 -0.5\n1 0.002 0.0015 -0.0002 -0.2 -0.6\n2 0.0005 0.0004 -0.0003 -0.15 -0.7\n\nend\n"
_BAD_TLEVEL = "SYNTHETIC deliberately invalid HYDRUS fixture\nTime rTop vTop vBot hTop hBot\n[d] [mm/d] [mm/d] [mm/d] [cm] [cm]\n0 1 2 3 4 5\n\nend\n"


def negative_cases():
    """Return invalid invocations; coordinator asserts exact deterministic codes."""
    return json.loads(json.dumps(_NEGATIVE_CASES))


def create(root: Path):
    """Create clearly synthetic assets exclusively under the shard asset prefix.

    Existing files are left untouched. This function performs no acceptance run.
    """
    root = Path(root).resolve()
    destination = root / "assets" / "earth-collection" / "groundwater_other"
    if not destination.resolve().is_relative_to(root):
        raise ValueError("Fixture destination escapes the supplied root")
    destination.mkdir(parents=True, exist_ok=True)
    files = {
        "synthetic_cases.json": json.dumps({"synthetic": True, "observations": "none", "operations": EXAMPLES}, indent=2) + "\n",
        "synthetic_negative_cases.json": json.dumps({"synthetic": True, "cases": _NEGATIVE_CASES}, indent=2) + "\n",
        "synthetic_T_LEVEL.OUT": _TLEVEL,
        "synthetic_bad_T_LEVEL.OUT": _BAD_TLEVEL,
        "SYNTHETIC.txt": "All arrays, coordinates, temperatures, flows, pumping rates, CPT samples and HYDRUS outputs in these fixtures are invented acceptance data. No field observations, external services or scientific engines were run to create them.\n",
    }
    result = {}
    for name, content in files.items():
        path = destination / name
        if path.is_symlink() or not path.resolve().is_relative_to(destination.resolve()):
            raise ValueError("Fixture file path is not confined to the asset directory")
        try:
            with path.open("x", encoding="utf-8", newline="\n") as handle:
                handle.write(content)
        except FileExistsError:
            pass
        result[name] = path.relative_to(root).as_posix()
    return result
